package kr.ac.kdu.focurve;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.mock.web.*;import org.springframework.jdbc.core.JdbcTemplate;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.security.*;
import static org.assertj.core.api.Assertions.*;
class AuthRecoveryScopeTest {
 @TempDir Path temp;final String install="a".repeat(32),ex="11111111-1111-4111-8111-111111111111",origin="https://localhost:29511",callback="chrome-extension://"+"a".repeat(32)+"/popup/popup.html";
 Path grant,marker;String digest;String blockedSQL="",databaseOverride="";ObjectMapper json=new ObjectMapper();
 void prepare()throws Exception{Path p=Files.createDirectory(temp.resolve(install));marker=Files.writeString(p.resolve("admission.closed"),"");grant=p.resolve("auth-recovery-grant.json");write(Instant.now().minusSeconds(2),Instant.now().plusSeconds(600));}
 void write(Instant begin,Instant end)throws Exception{Files.writeString(grant,json.writeValueAsString(Map.of("contract","FOCURVE_MEMBER_REAUTH_SCOPE_1","installation_id",install,"operation_id","b".repeat(32),"executor_id",ex,"owner_user_id","1","origin",origin,"callback",callback,"not_before",begin.toString(),"not_after",end.toString())));digest=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(grant)));}
 MemberAuth auth(){
  JdbcTemplate db=new JdbcTemplate(){@Override public <T>T queryForObject(String sql,Class<T> type){return type.cast(databaseOverride.isEmpty()?"focurve_user_"+install:databaseOverride);}@Override public <T>T queryForObject(String sql,Class<T> type,Object...args){return type.cast(Long.valueOf(1));}};
  var a=new MemberAuth(db,json,origin,Base64.getEncoder().encodeToString(new byte[32]),callback){@Override Map<String,Object> one(String sql,Object...args){if(!blockedSQL.isEmpty()&&sql.contains(blockedSQL))return Map.of("id",1L);return sql.contains("extension_installations")?Map.of("id",ex,"current_user_id",1L,"proof_hash",MemberAuth.hash("p".repeat(40))):null;}};
  a.recoveryGrant=grant.toString();a.recoveryGrantSHA=digest;a.recoveryGate=marker.toString();return a;
 }
 @Test void sameOwnerCandidateRequiresScopedAuthorityNotGlobalSwitch()throws Exception{prepare();var a=auth();a.sameOwnerRecoveryEnabled=true;a.recoveryGrant="";assertThatThrownBy(()->SameOwnerRecovery.begin(a,json.createObjectNode().put("recovery_owner_user_id","1"),ex,UUID.randomUUID().toString())).hasMessage("RECOVERY_SCOPE_REQUIRED");}
 @Test void validGrantAllowsOnlyBoundOwnerInstallationOriginAndCallback()throws Exception{prepare();var a=auth();var b=json.createObjectNode().put("recovery_owner_user_id","1").put("callback_uri",callback);assertThat(SameOwnerRecovery.begin(a,b,ex,UUID.randomUUID().toString()).path("owner").asText()).isEqualTo("1");b.put("recovery_owner_user_id","2");assertThatThrownBy(()->SameOwnerRecovery.begin(a,b,ex,UUID.randomUUID().toString())).hasMessage("RECOVERY_OWNER_MISMATCH");b.put("recovery_owner_user_id","1");assertThatThrownBy(()->SameOwnerRecovery.begin(a,b,"22222222-2222-4222-8222-222222222222",UUID.randomUUID().toString())).hasMessage("RECOVERY_OWNER_MISMATCH");}
 @Test void expirationTamperingAndOpenFocusGateReject()throws Exception{prepare();String old=digest;Files.writeString(grant,"{}");assertThatThrownBy(()->AuthRecoveryScope.read(grant.toString(),old,marker.toString(),Instant.now())).hasMessage("RECOVERY_SCOPE_CHANGED");write(Instant.now().minusSeconds(100),Instant.now().minusSeconds(1));assertThatThrownBy(()->AuthRecoveryScope.read(grant.toString(),digest,marker.toString(),Instant.now())).hasMessage("RECOVERY_SCOPE_EXPIRED");write(Instant.now().minusSeconds(1),Instant.now().plusSeconds(1500));assertThatThrownBy(()->AuthRecoveryScope.read(grant.toString(),digest,marker.toString(),Instant.now())).hasMessage("RECOVERY_SCOPE_EXPIRED");Files.delete(marker);assertThatThrownBy(()->AuthRecoveryScope.read(grant.toString(),digest,marker.toString(),Instant.now())).hasMessage("RECOVERY_SCOPE_INVALID");}
 @Test void closedGateAllowsScopedAuthButNeverFocusRefreshOrPolicyMutation()throws Exception{prepare();var filter=new UserInstallGate(marker.toString(),"k".repeat(40),Instant.now().plusSeconds(600).toString(),null,grant.toString(),digest);
  for(String route:List.of("/api/v1/auth/login","/api/v1/extension-link-requests","/api/v1/extension-tokens")){var res=new MockHttpServletResponse();boolean[] reached={false};filter.doFilter(new MockHttpServletRequest("POST",route),res,(q,r)->reached[0]=true);assertThat(reached[0]).isTrue();}
  for(String route:List.of("/api/v1/sessions","/api/v1/extension-tokens/refresh","/api/v1/sites")){var res=new MockHttpServletResponse();filter.doFilter(new MockHttpServletRequest("POST",route),res,(q,r)->{throw new AssertionError("must not reach controller");});assertThat(res.getStatus()).isEqualTo(409);}
 }
 @Test void ordinaryLinkCannotUseRecoveryOnlyScope()throws Exception{prepare();var a=auth();assertThatThrownBy(()->SameOwnerRecovery.admit(a,"/extension-link-requests",json.createObjectNode().put("executor_id",ex))).hasMessage("RECOVERY_OWNER_MISMATCH");}

 @Test void statusRequiresInstallationProofAndNeverReturnsCredentialsOrFocusAuthority()throws Exception{prepare();var a=auth();var req=new MockHttpServletRequest("GET","/api/v1/install/auth-recovery");req.addHeader("X-Installation-Id",ex);req.addHeader("X-Installation-Proof","p".repeat(40));var r=SameOwnerRecovery.status(a,req);assertThat(r.path("focus_allowed").asBoolean(true)).isFalse();assertThat(r.path("owner_user_id").asText()).isEqualTo("1");assertThat(r.toString()).doesNotContain("proof","token","password");var bad=new MockHttpServletRequest();bad.addHeader("X-Installation-Id",ex);bad.addHeader("X-Installation-Proof","bad");assertThatThrownBy(()->SameOwnerRecovery.status(a,bad)).hasMessage("INVALID_INSTALLATION");}
 @Test void currentSessionsLocksReceiptsAndForeignDatabaseReject()throws Exception{prepare();var a=auth();var b=json.createObjectNode().put("recovery_owner_user_id","1").put("callback_uri",callback);for(String table:List.of("active_execution_locks","focus_sessions","event_receipts")){blockedSQL=table;assertThatThrownBy(()->SameOwnerRecovery.begin(a,b,ex,UUID.randomUUID().toString())).isInstanceOf(MemberAuth.Failure.class);}blockedSQL="";databaseOverride="operating_database";assertThatThrownBy(()->SameOwnerRecovery.begin(a,b,ex,UUID.randomUUID().toString())).hasMessage("RECOVERY_DATABASE_MISMATCH");}
 @Test void differentWebMemberAndUnverifiedLocalEvidenceCannotApprove()throws Exception{prepare();var a=auth();String link=UUID.randomUUID().toString();var body=json.createObjectNode().put("recovery_owner_user_id","1").put("callback_uri",callback);var proof=SameOwnerRecovery.begin(a,body,ex,link);var row=Map.<String,Object>of("id",link,"executor_id",ex,"execution_evidence",json.createObjectNode().set(SameOwnerRecovery.KEY,proof).toString());assertThatThrownBy(()->SameOwnerRecovery.validate(a,row,2L)).hasMessage("RECOVERY_OWNER_MISMATCH");assertThatThrownBy(()->SameOwnerRecovery.validate(a,row,1L)).hasMessage("EXECUTION_EVIDENCE_REQUIRED");}

 @Test void aNewRecoveryOperationCannotConsumeAnOlderLinkProof()throws Exception{prepare();var a=auth();String link=UUID.randomUUID().toString();var body=json.createObjectNode().put("recovery_owner_user_id","1").put("callback_uri",callback);var proof=SameOwnerRecovery.begin(a,body,ex,link);var row=Map.<String,Object>of("id",link,"executor_id",ex,"execution_evidence",json.createObjectNode().set(SameOwnerRecovery.KEY,proof).toString());var changed=(ObjectNode)json.readTree(Files.readString(grant));changed.put("operation_id","c".repeat(32));Files.writeString(grant,changed.toString());a.recoveryGrantSHA=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(grant)));assertThatThrownBy(()->SameOwnerRecovery.validate(a,row,1L)).hasMessage("RECOVERY_SCOPE_CHANGED");}
}
